import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"89. 现代风格：干净可读的 C","description":"The Little Book of C 中文版 — 89. 现代风格：干净可读的 C","frontmatter":{"title":"89. 现代风格：干净可读的 C","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","09-可移植与现代 C","中文"],"description":"The Little Book of C 中文版 — 89. 现代风格：干净可读的 C","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":"89","sidebarWeight":"89","alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/089-Modern Style Clean and Readable C","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/089-Modern Style Clean and Readable C"},"headers":[],"relativePath":"posts/c教程/zh-CN/09-可移植与现代 C/089-Modern Style Clean and Readable C.md","filePath":"posts/c教程/zh-CN/09-可移植与现代 C/089-Modern Style Clean and Readable C.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/09-可移植与现代 C/089-Modern Style Clean and Readable C.md"};function i(l,a,o,d,c,h){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/09-Portable and Modern C/089-Modern Style Clean and Readable C)</p><p>C 语言已经存在了 50 多年，并且仍在不断发展。现代 C (C11–C23) 将低级编程的强大功能与更安全的语法、更简洁的习惯用法以及使代码更易于推理的新功能结合起来。</p><p>本节将帮助您编写现代、可读且可维护的 C，一种感觉永恒的 C。</p><h4 id="第一步-清晰而非聪明" tabindex="-1">第一步：“清晰而非聪明” <a class="header-anchor" href="#第一步-清晰而非聪明" aria-label="Permalink to &quot;第一步：“清晰而非聪明”&quot;">​</a></h4><p>现代 C 语言的黄金法则是：</p><p>为人类而不是编译器编写。</p><p>编译器可以处理复杂性，但你的队友（以及未来的你）却不能。</p><p>坏的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (i = n; i--; ) a[i] = 0;</span></span></code></pre></div><p>好的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (int i = 0; i &lt; n; i++)</span></span>
<span class="line"><span>    a[i] = 0;</span></span></code></pre></div><p>可读性和简单性总是获胜。</p><h4 id="步骤-2-首选显式初始化" tabindex="-1">步骤 2. 首选显式初始化 <a class="header-anchor" href="#步骤-2-首选显式初始化" aria-label="Permalink to &quot;步骤 2. 首选显式初始化&quot;">​</a></h4><p>始终初始化变量。未初始化的内存是错误的最大来源之一。</p><p>坏的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x;</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, x);</span></span></code></pre></div><p>好的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 0;</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, x);</span></span></code></pre></div><p>还显式初始化数组和结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int arr[10] = {0};</span></span>
<span class="line"><span>struct Point p = { .x = 10, .y = 20 };</span></span></code></pre></div><h4 id="步骤-3-充分使用-const" tabindex="-1">步骤 3. 充分使用 const <a class="header-anchor" href="#步骤-3-充分使用-const" aria-label="Permalink to &quot;步骤 3. 充分使用 const&quot;">​</a></h4><p><code>const</code>传达意图，“这个值不应该改变。”</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const double PI = 3.14159;</span></span>
<span class="line"><span>void print(const char* message);</span></span></code></pre></div><p>这有助于编译器优化、防止意外修改并提高清晰度。</p><h4 id="步骤-4-更喜欢现代标准标头" tabindex="-1">步骤 4. 更喜欢现代标准标头 <a class="header-anchor" href="#步骤-4-更喜欢现代标准标头" aria-label="Permalink to &quot;步骤 4. 更喜欢现代标准标头&quot;">​</a></h4><p>使用标准标头，例如<code>&lt;stdint.h&gt;</code>,<code>&lt;stdbool.h&gt;</code>， 和<code>&lt;stddef.h&gt;</code>以获得清晰、可移植的代码。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>#include &lt;stdbool.h&gt;</span></span>
<span class="line"><span>bool is_even(uint32_t n) {</span></span>
<span class="line"><span>    return (n % 2) == 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>避免使用旧式 typedef，例如<code>typedef unsigned long ulong;</code>除非它改善了意义。</p><h4 id="步骤-5-使用-bool-而不是-int-进行逻辑" tabindex="-1">步骤 5. 使用 bool 而不是 int 进行逻辑 <a class="header-anchor" href="#步骤-5-使用-bool-而不是-int-进行逻辑" aria-label="Permalink to &quot;步骤 5. 使用 bool 而不是 int 进行逻辑&quot;">​</a></h4><p>在旧的C中，人们使用<code>int</code>对于真/假。现代 C 为您提供<code>_Bool</code>通过<code>&lt;stdbool.h&gt;</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdbool.h&gt;</span></span>
<span class="line"><span>bool done = false;</span></span>
<span class="line"><span>if (!done) {</span></span>
<span class="line"><span>    done = true;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这提高了清晰度并使您的代码能够自我记录。</p><h4 id="第-6-步-编写小而集中的函数" tabindex="-1">第 6 步：编写小而集中的函数 <a class="header-anchor" href="#第-6-步-编写小而集中的函数" aria-label="Permalink to &quot;第 6 步：编写小而集中的函数&quot;">​</a></h4><p>保持功能简短，最好每个功能都有一个目的。</p><p>坏的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void handle_all() { /* does 10 things */ }</span></span></code></pre></div><p>好的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void read_input(void);</span></span>
<span class="line"><span>void process_data(void);</span></span>
<span class="line"><span>void write_output(void);</span></span></code></pre></div><p>这使得测试和调试变得更加容易。</p><h4 id="步骤-7-避免一切宏" tabindex="-1">步骤 7. 避免一切宏 <a class="header-anchor" href="#步骤-7-避免一切宏" aria-label="Permalink to &quot;步骤 7. 避免一切宏&quot;">​</a></h4><p>在早期的 C 语言中，宏被过度用于常量和函数。如今，更喜欢内联函数和<code>const</code>反而。</p><p>坏的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define SQUARE(x) ((x) * (x))</span></span></code></pre></div><p>好的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static inline int square(int x) { return x * x; }</span></span></code></pre></div><p>内联函数是类型安全且易于调试的。</p><h4 id="步骤-8-使用作用域变量和声明" tabindex="-1">步骤 8. 使用作用域变量和声明 <a class="header-anchor" href="#步骤-8-使用作用域变量和声明" aria-label="Permalink to &quot;步骤 8. 使用作用域变量和声明&quot;">​</a></h4><p>从 C99 开始，您可以在靠近使用变量的位置声明变量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (int i = 0; i &lt; n; i++) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, i);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>避免使变量的存活时间超过必要的时间，这可以减少错误并澄清范围。</p><h4 id="第-9-步-拥抱-c23-功能" tabindex="-1">第 9 步：拥抱 C23 功能 <a class="header-anchor" href="#第-9-步-拥抱-c23-功能" aria-label="Permalink to &quot;第 9 步：拥抱 C23 功能&quot;">​</a></h4><p>C23 使语法现代化并使 C 更安全、更具表现力。</p><p>亮点：</p><p>-<code>typeof</code>，自动重用变量类型 -<code>nullptr</code>, 替换<code>NULL</code> -<code>[[nodiscard]]</code>, 如果函数返回被忽略则发出警告 -<code>auto</code>、局部变量的类型推断</p><ul><li>UTF-8 字符支持和字符串文字 -<code>alignof</code>/<code>alignas</code>精确的内存布局</li></ul><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[[nodiscard]] int divide(int a, int b) {</span></span>
<span class="line"><span>    if (b == 0) return 0;</span></span>
<span class="line"><span>    return a / b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="步骤-10-小代码-现代-c23-示例" tabindex="-1">步骤 10. 小代码：现代 C23 示例 <a class="header-anchor" href="#步骤-10-小代码-现代-c23-示例" aria-label="Permalink to &quot;步骤 10. 小代码：现代 C23 示例&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdbool.h&gt;</span></span>
<span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>[[nodiscard]] static inline uint32_t add(uint32_t a, uint32_t b) {</span></span>
<span class="line"><span>    return a + b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    const uint32_t x = 10, y = 20;</span></span>
<span class="line"><span>    uint32_t sum = add(x, y);</span></span>
<span class="line"><span>    bool valid = (sum &gt; 0);</span></span>
<span class="line"><span>    if (valid)</span></span>
<span class="line"><span>        printf(&quot;Sum = %u\\n&quot;, sum);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>使用现代编译器（GCC 13+ 或 Clang 17+）进行编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -std=c23 modern.c -o modern</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sum = 30</span></span></code></pre></div><p>这段代码使用<code>[[nodiscard]]</code>,<code>bool</code>， 和<code>const</code>，提高风格和安全性的小细节。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>可读的 C 代码可持续数十年。内核、编译器和库中的最佳系统代码看起来很简单，因为它遵循清晰的模式：</p><ul><li>小而纯的函数。</li><li>显式类型。</li><li>内存处理方面没有什么意外。</li></ul><p>现代 C 并不意味着重写一切。意思是用心写C语言，清晰、正确、富有表现力。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>重构你的一个旧程序来使用<code>&lt;stdint.h&gt;</code>和<code>&lt;stdbool.h&gt;</code>.</li><li>用内联函数替换宏。 3.添加<code>const</code>只要有可能。</li><li>尝试编译<code>-std=c23</code>并探索新的警告。</li><li>尽可能使你的函数纯净且无副作用。</li></ol><p>接下来，您将通过练习：可移植多线程程序 (90) 来结束这一旅程，这是一个结合了从内存管理到线程和可移植性的所有内容的实践项目。</p>`,72)])])}const b=s(t,[["render",i]]);export{u as __pageData,b as default};
